<?php /** @var list<array<string,mixed>> $items */ /** @var int $subtotal */ /** @var int $discount */ /** @var int $total */ ?>
<div class="table-wrap"><table class="table"><thead><tr><th>Description</th><th class="num">Quantity</th><th class="num">Price each</th><th class="num">Amount</th></tr></thead><tbody>
    <?php foreach ($items as $it) : ?><tr><td><?= e($it['description']) ?></td><td class="num"><?= e(\Vertex\Services\BillingItems::qty((int) $it['quantity_x100'])) ?></td><td class="num"><?= e(money($it['unit_minor'])) ?></td><td class="num"><?= e(money($it['total_minor'])) ?></td></tr><?php endforeach; ?>
    <?php $coupon = $coupon ?? null; $credited = (int) ($credited ?? 0); if ($discount > 0 || $coupon !== null) : ?><tr><td colspan="3" class="num">Subtotal</td><td class="num"><?= e(money($subtotal)) ?></td></tr><?php if ($discount > 0) : ?><tr><td colspan="3" class="num">Discount</td><td class="num">− <?= e(money($discount)) ?></td></tr><?php endif; ?><?php if ($coupon !== null) : ?><tr><td colspan="3" class="num">Coupon <?= e($coupon[0]) ?></td><td class="num">− <?= e(money((int) $coupon[1])) ?></td></tr><?php endif; ?><?php endif; ?>
    <tr><td colspan="3" class="num"><strong>Total</strong></td><td class="num"><strong><?= e(money($total)) ?></strong></td></tr><?php if ($credited > 0) : ?><tr><td colspan="3" class="num">Credit notes</td><td class="num">− <?= e(money($credited)) ?></td></tr><tr><td colspan="3" class="num"><strong>To pay</strong></td><td class="num"><strong><?= e(money($total - $credited)) ?></strong></td></tr><?php endif; ?></tbody></table></div>
